H('256.d.1.A',4,"Financial reports such as the balance sheet are mainly used by owners, lenders, and:","Investors",["Strangers","Competitors' pets","Weather analysts"],"Stakeholders use reports.")
H('256.d.1.B',3,"Accurate accounting helps industry by:","Giving investors reliable information",["Hiding losses","Delaying taxes","Raising prices"],"Trust requires accuracy.")
H('256.d.1.B',4,"Lenders review a company's financial statements before approving a loan to judge its:","Ability to repay",["Logo design","Employee hobbies","Office decor"],"Statements show repayment ability.")
H('256.d.1.C',3,"GAAP stands for:","Generally Accepted Accounting Principles",["Great Accounting And Planning","General Asset And Profit","Government Accounting And Payroll"],"GAAP sets reporting standards.")
H('256.d.1.C',4,"GAAP is used so that financial statements are:","Consistent and comparable across companies",["Secret","Random","Ignored"],"Standards promote comparability.")
H('256.d.2.A',3,"An accountant who keeps client information private is practicing:","Confidentiality",["Fraud","Gossip","Negligence"],"Confidentiality is an ethical duty.")
H('256.d.2.A',4,"An accountant who is pressured to hide a loss from auditors should:","Refuse and follow ethical standards",["Hide it","Delete records","Quit silently"],"Integrity comes first.")
H('256.d.2.B',3,"Entry-level accounting jobs often require at least:","An associate or bachelor's degree",["No schooling","A medical degree","A law degree"],"Education varies.")
H('256.d.2.B',4,"A bookkeeper's primary role is to:","Record daily financial transactions",["Audit public companies","Set tax law","Design software"],"Bookkeepers record transactions.")
H('256.d.2.C',3,"The credential most associated with licensed public accountants is the:","CPA",["CNA","CEO","CFA"],"CPA is Certified Public Accountant.")
H('256.d.2.C',4,"A CPA candidate must pass the:","Uniform CPA Examination",["Driver's test","Bar exam","SAT"],"The exam is required for licensure.")
H('256.d.3.A',3,"Which step comes first in the accounting cycle?","Analyze source documents and transactions",["Close the books","Prepare financial statements","Post-closing trial balance"],"The cycle begins with analysis of transactions.")
