H('256.d.3.B',4,"A business buys $500 of supplies with cash. Total assets:","Stay the same",["Rise $500","Fall $500","Double"],"One asset replaces another.")
H('256.d.3.C',3,"A chart of accounts is a list of:","All accounts a business uses",["Employees","Customers' birthdays","Suppliers' logos"],"It organizes accounts.")
H('256.d.3.C',4,"In a typical numbering scheme, asset accounts usually begin with:","1",["5","4","9"],"Assets start at 1.")
H('256.d.3.D',3,"A general journal entry records the date, accounts, and:","Debit and credit amounts",["The weather","Employee names","Slogans"],"Entries need amounts.")
H('256.d.3.D',4,"When a business pays $200 cash for rent, which entry is correct?","Debit Rent Expense, credit Cash",["Debit Cash, credit Rent Expense","Debit Rent Expense, credit Revenue","Credit Rent Expense only"],"Expense up, cash down.")
H('256.d.3.E',3,"Posting means transferring journal entries to the:","General ledger accounts",["Bank statement","Invoice","Check stub"],"Posting updates ledgers.")
H('256.d.3.E',4,"After posting, a ledger account shows its running:","Balance",["Mascot","Slogan","Address"],"Balance updates after each entry.")
H('256.d.3.F',3,"A work sheet helps accountants:","Organize adjustments before preparing statements",["Hire staff","Pay taxes","Sell stock"],"Work sheets summarize adjustments.")
H('256.d.3.F',4,"On a work sheet, the adjusted trial balance is computed by combining the trial balance with:","Adjustments",["Slogans","Mascots","Taxes only"],"Adjustments update balances.")
