H('256.d.4.C',4,"To replenish petty cash, a business writes a check for the total of:","Expenses paid from the fund",["The full year's budget","Zero","Net income"],"The fund is restored to its set amount.")
H('256.d.4.D',3,"A bank service charge on the statement is recorded as:","A bank service expense",["Revenue","Owner's investment","A loan"],"Fees are expenses.")
H('256.d.4.D',4,"A note collected by the bank for the business increases the:","Checkbook balance",["Bank fee","Rent","Payroll"],"Collections add to the book balance.")
H('256.d.4.E',3,"Electronic funds transfer benefits a business by:","Moving money faster with fewer errors",["Using more paper","Slowing deposits","Hiding transactions"],"EFT is quick and accurate.")
H('256.d.4.E',4,"Direct deposit of payroll is an example of:","Electronic funds transfer",["Petty cash","Trial balance","Closing entry"],"Payroll can be paid electronically.")
H('256.d.6.A',3,"A vendor file stores information about:","Suppliers the business buys from",["Customers","Employees","Owners"],"It lists vendors.")
H('256.d.6.A',4,"A vendor file usually includes the vendor's name, address, and:","Payment terms",["Hobby","Pet","Birthday"],"Terms drive payments.")
H('256.d.6.B',3,"A purchase on account increases:","Accounts payable",["Accounts receivable","Cash","Revenue"],"Buying on credit creates a payable.")
