H('256.d.6.C',3,"The accounts payable subsidiary ledger has an account for each:","Vendor",["Customer","Employee","Owner"],"It tracks each supplier.")
H('256.d.6.C',4,"The total of the subsidiary ledger should equal the:","Accounts payable control account",["Cash account","Revenue account","Equity account"],"Subsidiary ledger totals agree with control accounts.")
